function u(e){return e.filter(n=>n.estActive&&n.code.toUpperCase()!=="CDF")}function i(e,n){if(!e||!n)return null;let t=null;for(const o of e.cours){const r=o.date.slice(0,10);r>n||(!t||r>t.date)&&(t={cours:Number(o.cours),date:r})}return t}function s(e,n){return Math.round(e*n*100)/100}function c(e){if(!(e.montantDevise>0))return`Saisissez le montant en ${e.code}, positif · le sens est celui de la ligne.`;if(e.cours===null)return null;if(!(e.cours>0))return`Le cours de ${e.code} doit être positif.`;const n=s(e.montantDevise,e.cours);return Math.abs(n-e.francs)>.01+e.montantDevise*5e-7?`${e.montantDevise} ${e.code} au cours de ${e.cours} font ${n} CDF, et la ligne porte ${e.francs}.`:null}export{s as a,i as c,u as d,c as m};
